import ghidra.app.decompiler.*; import ghidra.app.script.GhidraScript; import ghidra.program.model.listing.*;
public class Find150Consumers extends GhidraScript { public void run()throws Exception{DecompInterface d=new DecompInterface();d.openProgram(currentProgram);int n=0;for(Function f:currentProgram.getFunctionManager().getFunctions(true)){if(monitor.isCancelled())break;DecompileResults r=d.decompileFunction(f,30,monitor);if(r.getDecompiledFunction()==null)continue;String c=r.getDecompiledFunction().getC();if(c.contains("+ 0x150")||c.contains("+0x150")||c.contains("0x150))")){println("=== "+f.getEntryPoint()+" "+f.getName()+" ===");for(String line:c.split("\n")){if(line.contains("0x150")||line.contains("0x2c")||line.contains("0x30")||line.contains("0x34")||line.contains("0x38"))println(line);}if(++n>=80)break;}}d.dispose();}}
